create table public.audit_log (id bigint not null, tenant_id uuid, client_id uuid, changed_by_email text, field_name text, old_value text, new_value text, changed_at timestamp with time zone default now());
create table public.auto_pay_enrollments (id uuid not null default gen_random_uuid(), tenant_id uuid, client_id uuid not null, user_id uuid not null, payment_method text not null, gcash_mobile text, bank_name text, bank_account_name text, bank_account_number text, provider text, provider_customer_ref text, provider_payment_method_ref text, status text not null default 'Setup Pending'::text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.billing (id uuid not null default gen_random_uuid(), tenant_id uuid, client_id uuid, bill_id text, status text, bill_type text, bill_date date, due_date date, amount_due numeric, billing_cycle text, billing_period_start date, billing_period_end date, disconnect_date date, terminate_date date, original_amount numeric(12,2), discount_amount numeric(12,2) default 0, final_amount numeric(12,2), discount_reason text, paid_at timestamp with time zone);
create table public.billing_cycle_settings (id uuid not null default gen_random_uuid(), cycle_code text not null, cycle_name text not null, bill_day integer, due_day integer, disconnect_day integer, terminate_day integer, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.billing_reminders_sent (billing_id uuid not null, kind text not null, sent_at timestamp with time zone not null default now());
create table public.client_services (id uuid not null default gen_random_uuid(), tenant_id uuid not null, client_id uuid not null, plan_id uuid, pppoe_name text, installation_status text, install_date date, technician_user_id uuid, billing_cycle_id uuid, status text not null default 'active'::text, started_at timestamp with time zone, ended_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.clients (tenant_id uuid default gen_random_uuid(), customer_name text, install_date date, plan_name text, area text, installation_status text, account_status text, account_id text, mobile_number text, pppoe_name text, map_location text, technicians text, id uuid not null default gen_random_uuid(), latitude double precision, longitude double precision, user_id uuid, referral_code text default generate_client_referral_code(), billing_cycle text default 'mid_month'::text, billing_day integer, due_day integer, disconnect_day integer, terminate_day integer, email text, birth_date date, gender text, address text, disconnection_flag boolean not null default false, disconnection_flagged_at timestamp with time zone, referred_by_client_id uuid);
create table public.internet_plans (id uuid not null default gen_random_uuid(), tenant_id uuid, plan_name text not null, price numeric not null, speed text, active boolean default true);
create table public.payment_submissions (id uuid not null default gen_random_uuid(), tenant_id uuid, client_id uuid not null, user_id uuid not null, service_request_id uuid not null, amount_claimed numeric not null, payment_method text not null, reference_number text, bank_name text, payment_date date not null default CURRENT_DATE, proof_path text, status text not null default 'Pending'::text, reviewed_at timestamp with time zone, reviewed_by uuid, payment_id uuid, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), reject_reason text, reject_note text);
create table public.payments (id uuid not null default gen_random_uuid(), tenant_id uuid, client_id uuid, billing_id uuid, payment_id text, receipt_number text, amount_paid numeric, payment_date date, payment_method text, service_request_id uuid);
create table public.push_config (id boolean not null default true, secret text not null default encode(gen_random_bytes(24), 'hex'::text));
create table public.referral_rewards (id uuid not null default gen_random_uuid(), referral_id uuid not null, referrer_client_id uuid not null, amount numeric(12,2) not null default 250.00, status text not null default 'Pending'::text, eligible_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), withdrawal_id uuid);
create table public.referral_withdrawals (id uuid not null default gen_random_uuid(), referral_id uuid not null, referrer_client_id uuid not null, gross_amount numeric(12,2) not null default 250.00, transfer_fee numeric(12,2) not null default 5.00, net_amount numeric(12,2) not null default 245.00, payout_method text not null, payout_account_name text not null, payout_account_number text not null, payout_notes text, status text not null default 'Pending'::text, accounting_notes text, requested_at timestamp with time zone not null default now(), processed_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.referrals (id uuid not null default gen_random_uuid(), referrer_client_id uuid not null, referred_client_id uuid, referral_code text not null, installation_discount numeric default 0, installation_discount_status text default 'Pending'::text, status text default 'Pending'::text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), bonus_amount numeric(12,2) default 250.00, bonus_status text default 'Pending'::text, bonus_eligible_at timestamp with time zone, bonus_paid_at timestamp with time zone);
create table public.repair_records (id uuid not null default gen_random_uuid(), client_id uuid not null, technician text, repair_date date not null default CURRENT_DATE, problem_description text not null, resolution text, status text not null default 'Completed'::text, created_at timestamp with time zone not null default now(), technician_user_id uuid, service_request_id uuid, job_type text not null default 'repair'::text, latitude double precision, longitude double precision, accepted_at timestamp with time zone, technician_phone text, accept_sms_sent_at timestamp with time zone);
create table public.service_requests (id uuid not null default gen_random_uuid(), user_id uuid not null, client_id uuid, request_type text not null default 'plan_change'::text, requested_plan text, description text, status text not null default 'Pending'::text, referral_code text, referred_by_client_id uuid, referred_by_client_name text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), issue_type text, requested_amount numeric, effective_at timestamp with time zone, payment_mode text, payment_method text, payment_reference text, bank_name text, bank_account_name text, bank_account_number text, gcash_mobile text, payment_proof_path text, latitude double precision, longitude double precision, installation_location_type text, installation_area text, installation_region_code text, installation_province_code text, installation_city_code text, installation_barangay_code text, installation_purok text);
create table public.tenant_users (user_id uuid not null default gen_random_uuid(), tenant_id uuid default gen_random_uuid(), role text);
create table public.tenants (name text, id uuid not null default gen_random_uuid());
